def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full separator bands partition the grid into independent tiles.
    sep_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}
    def ranges(n, cuts):
        result = []
        start = 0
        for i in range(n):
            if i in cuts:
                if start < i:
                    result.append(range(start, i))
                start = i + 1
        if start < n:
            result.append(range(start, n))
        return result
    row_groups = ranges(h, sep_rows)
    col_groups = ranges(w, sep_cols)
    # The non-separator background is the common most frequent tile color;
    # the single exceptional cell-color is counted as a marker.
    from collections import Counter
    counts = Counter(grid[r][c] for rr in row_groups for r in rr for cc in col_groups for c in cc)
    background = counts.most_common(1)[0][0]
    out = []
    for rr in row_groups:
        row = []
        for cc in col_groups:
            marker_count = sum(grid[r][c] != background for r in rr for c in cc)
            row.append(1 if marker_count == 2 else background)
        out.append(row)
    return out

